-- OpsCore v0.11.45 field AI, offline conflict resolution and labor tracking.
-- These objects are tenant-scoped and do not enable any external AI provider by default.
CREATE TABLE IF NOT EXISTS sync_conflicts (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_event_id text NOT NULL, entity_id text NOT NULL, operation text NOT NULL, payload_json jsonb NOT NULL, error_code text NOT NULL, retryable boolean NOT NULL, status text NOT NULL CHECK(status IN ('open','resolved','superseded')), resolution_json jsonb, resolved_by TEXT REFERENCES users(id) ON DELETE SET NULL, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_sync_conflicts_org_status ON sync_conflicts(organization_id,status,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sync_conflict_event_error ON sync_conflicts(organization_id,actor_user_id,client_event_id,error_code);
CREATE TABLE IF NOT EXISTS time_entries (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, technician_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, appointment_id TEXT REFERENCES appointments(id) ON DELETE SET NULL, started_at timestamptz NOT NULL, ended_at timestamptz, status text NOT NULL CHECK(status IN ('running','stopped','void')), minutes integer CHECK(minutes IS NULL OR (minutes >= 1 AND minutes <= 1440)), note text NOT NULL DEFAULT '', source text NOT NULL DEFAULT 'manual', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_time_entries_org_tech_status ON time_entries(organization_id,technician_id,status,started_at);
CREATE INDEX IF NOT EXISTS idx_time_entries_org_wo_started ON time_entries(organization_id,work_order_id,started_at);

CREATE UNIQUE INDEX IF NOT EXISTS uq_time_entry_running_technician ON time_entries(organization_id,technician_id) WHERE status='running';
